document.addEventListener('DOMContentLoaded',()=>{const videoPoster=document.getElementById('videoPoster');const initialPlayBtn=document.getElementById('ytPlayPause');if(videoPoster){videoPoster.addEventListener('click',loadAndPlayVideo);videoPoster.addEventListener('keydown',(e)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();loadAndPlayVideo()}})}
if(initialPlayBtn){initialPlayBtn.addEventListener('click',loadAndPlayVideo,{once:!0})}});function loadAndPlayVideo(){const container=document.getElementById('ytVideoContainer');const img=document.getElementById('videoPoster');if(!img||!container)return;const video=document.createElement('video');video.id='ytVideo';video.controls=!1;video.preload='metadata';video.poster=img.src;video.style.cssText='width:100%; height:100%; object-fit:cover; display:block; max-height:600px; border-radius:8px;';video.setAttribute('playsinline','');const source=document.createElement('source');source.src='https://gitechnolo.github.io/biotechproject/Biotech-file/images/Biotech-menu/Auto_del_futuro-Metropoli.mp4';source.type='video/mp4';video.appendChild(source);container.replaceChild(video,img);const controls=document.querySelector('.yt-video-controls');initializeVideoControls(video,controls);video.play().catch(e=>console.log("Riproduzione manuale richiesta:",e));if(typeof triggerWandererSync==='function'){triggerWandererSync()}}
function initializeVideoControls(video,controls){if(!controls)return;const playPauseBtn=controls.querySelector('#ytPlayPause');const playPauseIcon=controls.querySelector('#ytPlayPauseIcon');const progressBar=controls.querySelector('#ytProgress');const currentTime=controls.querySelector('#ytCurrentTime');const durationEl=controls.querySelector('#ytDuration');const volumeControl=controls.querySelector('#ytVolume');const muteBtn=controls.querySelector('#ytMute');const muteIcon=controls.querySelector('#ytMuteIcon');const fullscreenBtn=controls.querySelector('#ytFullscreen');const exitFullscreenBtn=controls.querySelector('#ytExitFullscreen');const formatTime=(time)=>{const minutes=Math.floor(time/60);const seconds=Math.floor(time%60);return minutes+':'+(seconds<10?'0':'')+seconds};if(playPauseBtn){const newPlayBtn=playPauseBtn.cloneNode(!0);playPauseBtn.parentNode.replaceChild(newPlayBtn,playPauseBtn);const newIcon=newPlayBtn.querySelector('#ytPlayPauseIcon')||playPauseIcon;newPlayBtn.addEventListener('click',()=>{if(video.paused){video.play().catch(e=>console.error("Errore riproduzione:",e))}else{video.pause()}});video.addEventListener('play',()=>{if(newIcon)newIcon.textContent='⏸️'});video.addEventListener('pause',()=>{if(newIcon)newIcon.textContent='▶️'})}
video.addEventListener('timeupdate',()=>{if(progressBar)progressBar.value=video.currentTime;if(currentTime)currentTime.textContent=formatTime(video.currentTime);});video.addEventListener('loadedmetadata',()=>{if(progressBar)progressBar.max=video.duration;if(durationEl)durationEl.textContent=formatTime(video.duration);if(currentTime)currentTime.textContent=formatTime(video.currentTime);});progressBar?.addEventListener('input',()=>{video.currentTime=progressBar.value});volumeControl?.addEventListener('input',()=>{video.volume=volumeControl.value;if(muteIcon)muteIcon.textContent=(video.muted||volumeControl.value==0)?'🔇':'🔊'});video.addEventListener('volumechange',()=>{if(muteIcon)muteIcon.textContent=(video.muted||video.volume===0)?'🔇':'🔊'});muteBtn?.addEventListener('click',()=>{video.muted=!video.muted;if(muteIcon)muteIcon.textContent=video.muted?'🔇':'🔊'});fullscreenBtn?.addEventListener('click',()=>{if(video.requestFullscreen)video.requestFullscreen();else if(video.webkitRequestFullscreen)video.webkitRequestFullscreen();else if(video.msRequestFullscreen)video.msRequestFullscreen();});exitFullscreenBtn?.addEventListener('click',()=>{if(document.exitFullscreen)document.exitFullscreen();else if(document.webkitExitFullscreen)document.webkitExitFullscreen();else if(document.msExitFullscreen)document.msExitFullscreen();});document.addEventListener('fullscreenchange',()=>{const isFs=document.fullscreenElement===video;if(fullscreenBtn)fullscreenBtn.style.display=isFs?'none':'flex';if(exitFullscreenBtn)exitFullscreenBtn.style.display=isFs?'flex':'none'});video.addEventListener('keydown',(e)=>{if(e.code==='Space'){e.preventDefault();controls.querySelector('#ytPlayPause')?.click()}else if(e.code==='KeyM'){e.preventDefault();muteBtn?.click()}else if(e.code==='KeyF'){e.preventDefault();fullscreenBtn?.click()}})}
function fadeEffect(){let text=document.getElementById("fadingText");if(!text)return;let visible=!0;setInterval(()=>{visible=!visible;text.classList.toggle("fade",!visible)},2000)}
window.addEventListener("load",fadeEffect);function triggerWandererSync(){const logStyle="color: #B5EAD7; font-weight: bold; font-family: 'Courier New', monospace; background: #1a1a1a; padding: 2px 5px; border-radius: 3px; border: 1px solid rgba(0, 230, 118, 0.3);";console.log("%c[VIDEO_SYNC] BiotechProject: We are all wanderers searching for the truth...",logStyle)}